```js
import { createHash } from 'node:crypto';

/**
 * Compute the SHA-256 digest of `value` and return it as a lowercase hex string.
 *
 * Strings are hashed as UTF-8. Buffers and typed arrays are hashed byte for
 * byte. Any other value is converted to its string form first.
 *
 * @param {string | Buffer | Uint8Array | unknown} value
 * @returns {string} 64-character hex digest
 */
export function checksum(value) {
  let data;

  if (typeof value === 'string') {
    data = value;
  } else if (Buffer.isBuffer(value)) {
    data = value;
  } else if (value instanceof Uint8Array) {
    data = Buffer.from(value.buffer, value.byteOffset, value.byteLength);
  } else {
    data = String(value);
  }

  return createHash('sha256').update(data, typeof data === 'string' ? 'utf8' : undefined).digest('hex');
}

export default checksum;
```

Named export `checksum(value)` plus a default export so both `import { checksum }` and `import checksum` work. Typed arrays are sliced by `byteOffset`/`byteLength` so views into larger backing buffers hash only their own bytes.

